namespace{bool tracking=false;uint64_t allocations=0;void check(bool b,const char*m){if(!b)throw std::logic_error(m);}}
void*operator new(std::size_t n){if(tracking)++allocations;if(auto*p=std::malloc(n?n:1))return p;throw std::bad_alloc();}void*operator new[](std::size_t n){return::operator new(n);}void operator delete(void*p)noexcept{std::free(p);}void operator delete[](void*p)noexcept{std::free(p);}void operator delete(void*p,std::size_t)noexcept{std::free(p);}void operator delete[](void*p,std::size_t)noexcept{std::free(p);}
namespace{using T=ks::StatePartNavigationService;using Event=std::tuple<bool,uint32_t,uint8_t,unsigned>;
int history(uint32_t a){a&=0xffffff;return a<0x400000||(a>=0xfffd10&&a<0xffffa0)?int(a):-1;}
struct Resolver{ks::StateFieldCoordinator::Handler field(uint8_t category,uint32_t id)const{check(category<9&&id==category,"Numeric handler binding");return ks::StateFieldCoordinator::Handler(category);}ks::StatePackFieldsTask::Kind operator()(uint32_t id)const{check(id<6,"Numeric packing binding");return ks::StatePackFieldsTask::Kind(id);}};
struct Resource{std::vector<uint8_t>m=std::vector<uint8_t>(1<<24);std::array<Event,8>events{};unsigned size=0,cost=0,lastTime=0;int previous=-1;void byte(uint32_t a,uint8_t v){m[a&0xffffff]=v;}void wide(uint32_t a,uint32_t v){for(unsigned n=0;n<4;++n)byte(a+n,uint8_t(v>>(24-8*n)));}void word(uint32_t a,uint16_t v){byte(a,v>>8);byte(a+1,v);}void see(bool write,uint32_t a,uint8_t v,unsigned dt){check(a<m.size()&&dt&&dt<=cost&&(!size||dt>=lastTime)&&size<events.size(),"Pure navigation callback address/order/time");events[size++]={write,a,v,dt};lastTime=dt;}uint8_t read(uint32_t a,unsigned dt){check(a<0xfff000||a>=0xfffc00,"Pure navigation observed a CPU continuation frame");const auto v=a==0x400004||a==0x600004?uint8_t(255):m[a];see(false,a,v,dt);return v;}void write(uint32_t a,uint8_t v,unsigned dt){check(a<0xfff000||a>=0xfffc00,"Pure navigation wrote a CPU continuation frame");see(true,a,v,dt);m[a]=v;previous=history(a);}void phase(unsigned c){size=lastTime=0;cost=c;}};
struct Config{unsigned kind=0,seed=0;uint16_t event=0x010b;bool pressed=true;uint8_t page=0,edit=0,screen=11,hardware=1;uint32_t source=0x30000,live=0x34000;bool sceneNested=false,evolving=false;uint8_t mode=1,multi=0,special=0,selected=1,enabled=1;};
void seed(Resource&r,const Config&c){std::fill(r.m.begin(),r.m.end(),0);r.previous=-1;r.wide(0x167bc,c.source);r.wide(0x167c0,c.live);r.wide(0x167a6,0);r.wide(0x167f0,0x40002);r.byte(0x16790,c.page);r.byte(0x16784,c.edit);r.byte(0x16785,c.screen);r.byte(0x16787,c.hardware?0:2);r.byte(0x16792,1);r.byte(0x167fb,2);r.byte(0x167ba,0);r.byte(0x167ac,1);r.byte(0x167ad,3);r.byte(0xffec14,c.hardware);r.wide(0xffec10,12345);r.byte(0x169ed,127);r.byte(0x169f7,0);r.byte(0x169f9,0);r.byte(0xfffeb1,255);r.byte(0xffff51,0);r.byte(0xffff62,255);r.word(0xffed6c,0);r.word(0xffed6e,0);r.byte(0xffed6d,45);r.byte(0xffed6f,17);r.word(0x159f2,0x1234);
 for(unsigned n=0;n<256;++n){r.byte(c.source+n,uint8_t(c.seed+n));r.byte(c.live+n,uint8_t(c.seed+n+1));r.byte(71586+n,127);r.byte(68974+n,0);r.word(0x15200+2*n,uint16_t(n*127));r.byte(0x816000+n,uint8_t(c.seed+n));}for(unsigned n:{0u,139u,222u,223u,224u,225u,226u})r.byte(c.source+n,0);
 for(unsigned n=0;n<78;++n){const auto d=0x40000+n*0x1000;r.wide(0x101ae + 4*n,d);r.byte(d,1);r.byte(d+1,0);for(unsigned item=0;item<256;++item){const auto at=d+2+20*item;for(unsigned k=0;k<16;++k)r.byte(at+k,uint8_t(65+k));r.byte(at+16,10);r.byte(at+18,0);r.byte(at+19,127);}}
 for(unsigned n=0;n<47;++n){r.byte(0xfd66+8*n,0);r.byte(0xfd68+8*n,255);r.byte(0xfd69+8*n,3);r.byte(0xfd6c+8*n,0);r.byte(0xfd6d+8*n,1);}for(unsigned n=0;n<9;++n)r.wide(0x1013e + 4*n,n);for(unsigned n=0;n<6;++n)r.wide(71306+4*n,n);for(unsigned n=0;n<48;++n){r.byte(0x1c0+5*n,uint8_t(n%4));r.byte(0x1c1+5*n,1);r.byte(0x1c2+5*n,255);r.byte(0x1c3+5*n,7);r.byte(0x1c4+5*n,uint8_t(n%4));}
 for(unsigned n=0;n<16;++n)r.byte(0x1733c+n,uint8_t(65+n));r.byte(0x1734c,0);
 if(c.sceneNested||c.special){
  for(unsigned slot=0;slot<256;++slot){const auto at=0x17560+20*slot;r.wide(at,c.source+256*(slot%4));r.byte(at+4,uint8_t(slot%4));r.word(at+8,uint16_t(slot<4?1:0));r.byte(at+6,uint8_t(c.seed));r.byte(at+12,uint8_t(c.seed&7));}
  for(unsigned part=0;part<4;++part){r.wide(0x174ae +20*part,c.source+256*part);for(unsigned n=4;n<20;++n)r.byte(0x174ae +20*part+n,uint8_t(c.seed+n));for(unsigned n=0;n<256;++n)r.byte(c.source+256*part+n,uint8_t((c.seed*19+n*3)%128));for(unsigned n:{0u,139u,222u,223u,224u,225u,226u})r.byte(c.source+256*part+n,0);r.byte(c.source+256*part+73,uint8_t(c.seed%3));r.byte(c.source+256*part+76,uint8_t(c.seed%4));}
  r.byte(0x17526,uint8_t(c.seed%4));r.byte(0x16798,3);r.byte(0x167ba,0);r.byte(0x174a6,uint8_t(c.seed%8));r.byte(0x1755e,uint8_t(c.seed&1?255:0));r.word(0x15138,0x4470);r.word(0x1512e,1);r.word(0x159f2,0xffff);r.wide(0x1748e,0x36000);r.byte(0x17492,1);r.byte(0x17493,0);r.byte(0x1679d,64);r.byte(0x1679e,0);r.byte(0x1679f,0);r.byte(0x167a0,0);r.byte(0xfd66+8*28,8);r.byte(0xffec22,0);r.byte(0xffff62,0);
  for(unsigned n=0;n<64;++n)r.byte(0x36000+n,uint8_t(c.seed+n));for(unsigned n=0;n<16;++n){r.byte(0x36000+16+2*n,uint8_t(16+n));r.byte(0x36000+17+2*n,uint8_t(n&1?1:0));r.byte(0x17495+n,uint8_t(c.seed+n));}
  for(unsigned page=0;page<16;++page)for(unsigned n=0;n<256;++n){const auto pos=n%64;r.byte(0x85ec00+page*256+n,pos>=16&&pos<48?uint8_t(pos&1?1:16+(pos-16)/2):uint8_t(n+c.seed));}
 }
 r.byte(0x167ba,c.mode);r.byte(0x167bb,uint8_t(c.seed&1));r.byte(0x167d5,c.multi);r.byte(0x1679e,c.special);r.byte(0x16799,c.selected);r.byte(0x167b8,1);r.byte(0x167b9,1);r.byte(0x167d0,1);r.byte(0x167d1,1);r.byte(0x167d4,1);r.byte(0x16798,1);r.byte(0x16792,0);r.byte(0x167fb,0);r.byte(0x167da,uint8_t(c.seed%25));r.byte(0x167d7,uint8_t(c.seed%16));r.byte(0x167d8,uint8_t(c.seed&1));r.byte(0x167d9,uint8_t(c.seed%59));
 for(unsigned n=0;n<256;++n){r.byte(0x101a4+2*n,uint8_t(1u<<(n%4)));r.byte(0x101a5+2*n,c.enabled);}for(unsigned part=0;part<5;++part)for(unsigned n=0;n<256;++n){r.byte(0x168fc+part*256+n,0);r.byte(0x16e12+part*256+n,0);}

}
}

int main(){try{auto resource=std::make_unique<Resource>();auto storage=std::make_unique<std::aligned_storage_t<sizeof(T),alignof(T)>>();std::vector<unsigned char>snapshot(sizeof(T));uint64_t graphs=0,phases=0,rejects=0,guards=0,reads=0,writes=0,nestedGraphs=0;uint32_t components=0;Resolver resolver;
 const auto run=[&](Config c){seed(*resource,c);auto&r=*resource;T::Input in{c.event,c.pressed};tracking=true;auto*s=new(storage.get())T(T::Kind(c.kind),in);tracking=false;uint64_t count=0;unsigned hooks=0;while(!s->complete()){
 if(c.evolving)if(const auto*field=s->field())if(const auto*ui=field->refresh())if(const auto*bank=ui->task<ks::StateBankNavigationTask>()){
  if(!(hooks&1)&&bank->stage()==ks::StateBankNavigationTask::Stage::ReadRefreshSpecial){r.byte(0x1679e,0);hooks|=1;}
  if(hooks==1&&bank->stage()==ks::StateBankNavigationTask::Stage::ReadRefreshLatch){r.byte(0x1679e,8);r.byte(0x1679d,64);r.byte(0x16793,28);r.byte(0x16792,1);r.byte(0x1679f,0);r.byte(0x16790,0);r.byte(0x167a0,0);hooks|=2;}
 }
 const auto cost=s->nextClocks(r.previous);check(cost,"Missing pure navigation phase");r.phase(cost);const auto prev=r.previous;std::memcpy(snapshot.data(),s,sizeof(T));tracking=true;const auto rejected=s->advanceBefore(cost-1,[&](uint32_t a,unsigned dt){return r.read(a,dt);},[&](uint32_t a,uint8_t v,unsigned dt){r.write(a,v,dt);},resolver,prev);tracking=false;check(!rejected&&!r.size&&!std::memcmp(snapshot.data(),s,sizeof(T)),"Insufficient navigation budget changed state/resources");++rejects;tracking=true;const auto used=s->advanceBefore(cost,[&](uint32_t a,unsigned dt){++reads;return r.read(a,dt);},[&](uint32_t a,uint8_t v,unsigned dt){++writes;r.write(a,v,dt);},resolver,prev);tracking=false;check(used==cost,"Pure navigation phase cost");if(s->effect().write)r.previous=-1;if(++count>=1500000){std::cerr<<"stall kind="<<c.kind<<" seed="<<c.seed<<" component="<<unsigned(s->component())<<'\n';throw std::logic_error("Pure navigation graph stalled");}++phases;}
 const auto&out=s->summary();if(c.kind==3&&!c.evolving){uint8_t selected=c.selected;const auto delta=uint8_t(c.event);if(delta){if(!selected)selected=delta&128?1:4;else{selected=uint8_t(selected+delta);if(!selected)selected=4;else if(selected>4)selected=1;}}check(r.m[0x16799]==selected&&out.resolved&&out.ui,"Part selection independent wrap/closure oracle");check(out.routed==bool(c.enabled),"Enabled part routing independent oracle");}if((c.kind==0||c.kind==1)&&!c.pressed)check(out.release&&!out.ui&&!out.resolved&&!out.sceneEdit,"Released key independent oracle");if(c.evolving){check(hooks==3,"Recursive UI input landing missed");++nestedGraphs;}components|=s->components();tracking=true;s->~T();tracking=false;++graphs;
 };
 for(unsigned kind=0;kind<5;++kind)for(unsigned n=0;n<64;++n){Config c;c.kind=kind;c.seed=n;c.page=uint8_t(n%4);c.mode=uint8_t(n&1);c.multi=uint8_t(n&2);c.special=uint8_t(n&4?8:0);c.selected=uint8_t(n%5);c.enabled=uint8_t(n&8?0:1);c.event=uint16_t(((n*7)<<8)|uint8_t(n&1?255:1));c.pressed=!(n&16);run(c);}
 for(unsigned delta=0;delta<256;++delta)for(unsigned selected:{0u,1u,4u,255u})for(unsigned enabled:{0u,8u}){Config c;c.kind=3;c.seed=delta;c.event=uint16_t(0xab00|delta);c.selected=uint8_t(selected);c.enabled=uint8_t(enabled);c.page=1;run(c);}
 for(unsigned screen=0;screen<47;++screen){Config c;c.kind=3;c.event=0;c.edit=1;c.screen=uint8_t(screen);run(c);}
 for(unsigned kind=0;kind<4;++kind)for(unsigned n=0;n<8;++n){Config c;c.kind=kind;c.seed=n;c.sceneNested=true;c.evolving=true;c.page=kind==3?0:3;c.event=1;run(c);}
 for(unsigned kind=0;kind<4;++kind)for(uint32_t invalid:{0u,0x5006u,0xffefffu,0xfff000u,0xfff700u,0xfffbfcu,0xffff51u,0x42fff000u}){Config c;c.kind=kind;seed(*resource,c);resource->wide(0x167bc,invalid);check(!T::admitted(T::Kind(kind),{1,true},[&](uint32_t a){return resource->m[a];}),"Admission accepted unsupported pointer");++guards;}
 check(!allocations&&components==63,"Pure navigation closure/allocation contract");std::cout<<"PASS pure part navigation graphs="<<graphs<<" phases="<<phases<<" budgetRejects="<<rejects<<" reads="<<reads<<" writes="<<writes<<" guards="<<guards<<" recursiveUI="<<nestedGraphs<<" components="<<components<<" storage="<<sizeof(T)<<" allocations="<<allocations<<'\n';return 0;}catch(const std::exception&e){tracking=false;std::cerr<<e.what()<<'\n';return 1;}}
